/**
 * Shader des courants.
 *
 * ## L'idee mathematique
 *
 * Des lignes de courant : un premier bruit a grande echelle donne en chaque
 * point un angle d'ecoulement ; le point de lecture est advecte le long de
 * cet angle, puis tourne dans le repere local du courant et etire — l'echelle
 * varie vite en travers du flot, lentement le long. Le second bruit, lu dans
 * ce repere anisotrope, s'allonge donc en filaments qui suivent le champ,
 * sans qu'aucune ligne ne soit tracee.
 *
 * ## Uniforms
 *
 * - `uTime` — temps en secondes, fourni par le moteur.
 * - `uResolution` — taille du canevas en pixels, fournie par le moteur.
 * - `uColorA` — l'eau profonde.
 * - `uColorB` — la teinte des courants.
 * - `uColorC` — la teinte des filaments rapides.
 * - `uSpeed` — vitesse d'advection.
 * - `uScale` — echelle du bruit ; plus haut, plus fin.
 * - `uStretch` — anisotropie ; plus haut, filaments plus longs.
 * - `uDetail` — nombre d'octaves du bruit fin, et donc son cout.
 */
export const CURRENTS_FRAGMENT = /* glsl */ `
precision highp float;

varying vec2 vUv;

uniform float uTime;
uniform vec2 uResolution;
uniform vec3 uColorA;
uniform vec3 uColorB;
uniform vec3 uColorC;
uniform float uSpeed;
uniform float uScale;
uniform float uStretch;
uniform float uDetail;

// Nombre pseudo-aleatoire : projection sur une direction arbitraire, sinus
// amplifie, partie fractionnaire.
float courantHash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

// Bruit de valeur : interpolation lissee entre les quatre coins de la cellule.
float courantNoise(vec2 p) {
  vec2 cell = floor(p);
  vec2 local = fract(p);
  vec2 smoothed = local * local * (3.0 - 2.0 * local);

  float a = courantHash(cell);
  float b = courantHash(cell + vec2(1.0, 0.0));
  float c = courantHash(cell + vec2(0.0, 1.0));
  float d = courantHash(cell + vec2(1.0, 1.0));

  return mix(mix(a, b, smoothed.x), mix(c, d, smoothed.x), smoothed.y);
}

// Somme d'octaves : chaque passe deux fois plus fine et deux fois plus faible.
float courantFbm(vec2 p, int octaves) {
  float total = 0.0;
  float amplitude = 0.5;
  float normalisation = 0.0;

  for (int i = 0; i < 5; i += 1) {
    if (i >= octaves) break;
    total += courantNoise(p) * amplitude;
    normalisation += amplitude;
    p *= 2.0;
    amplitude *= 0.5;
  }

  return total / max(normalisation, 0.0001);
}

void main() {
  float aspect = uResolution.x / max(uResolution.y, 1.0);
  vec2 p = vUv * vec2(aspect, 1.0) * max(uScale, 0.5);
  float t = uTime * uSpeed;
  int octaves = int(clamp(uDetail, 1.0, 5.0));

  // Le champ d'ecoulement : un bruit a grande echelle, trois octaves
  // suffisent — il ne porte que la direction, pas le detail.
  float champ = courantFbm(p * 0.35 + vec2(t * 0.5, -t * 0.3), 3);
  float angle = (champ - 0.5) * 9.42477;
  float c = cos(angle);
  float s = sin(angle);

  // Advection : le point de lecture remonte le courant, donc le motif
  // descend le long du champ au lieu de defiler tout droit.
  vec2 q = p - t * vec2(c, s) * 0.6;

  // Rotation dans le repere local, puis anisotropie : la coordonnee en
  // travers du flot est dilatee, le bruit y varie donc vite et s'allonge en
  // filaments le long du courant.
  vec2 repere = vec2(c * q.x + s * q.y, (-s * q.x + c * q.y) * max(uStretch, 1.0));

  float filament = courantFbm(repere, octaves);

  vec3 colour = mix(uColorA, uColorB, smoothstep(0.3, 0.68, filament));
  colour = mix(colour, uColorC, pow(smoothstep(0.5, 0.88, filament), 3.0));

  gl_FragColor = vec4(colour, 1.0);
}
`

sources.component.tsx:
/**
 * Courants : des filaments de bruit etires le long d'un champ d'ecoulement.
 *
 * ## Le principe
 *
 * Un premier bruit a grande echelle donne en chaque point un angle
 * d'ecoulement ; le point de lecture est advecte le long de cet angle, tourne
 * dans le repere local et etire — le bruit fin, lu dans ce repere anisotrope,
 * s'allonge en filaments qui suivent le champ sans qu'aucune ligne ne soit
 * tracee.
 *
 * ## Ce que ce composant delegue
 *
 * Il ne porte que ce qui le distingue : son shader, ses reglages et son repli.
 * La lecture des tokens, leur conversion en flottants et leur relecture au
 * changement de theme viennent du moteur — les recopier ici en ferait autant
 * de versions a maintenir qu'il y a de fonds.
 *
 * Le repli n'est pas une precaution : il est affiche pendant le chargement du
 * backend, quand WebGL manque, quand l'arbitre refuse la surface — il n'en
 * accorde qu'une par backend — et sous mouvement reduit.
 *
 * @module
 */

import {
  mergePresentation,
  useOnReady,
  useTokenShader,
  type Customisable,
  type ReadyCallback,
  type ShaderColour,
} from '@odoro-cli/engine'
import { type ReactElement } from 'react'

import { CURRENTS_FRAGMENT } from './currents.shader.js'

/** Ce que l'echappatoire recoit. */
export interface CurrentsControls {
  /** Couleurs effectivement transmises au shader. */
  readonly colours: readonly ShaderColour[]
  /** Motif du refus, s'il y en a un. */
  readonly refused: string | undefined
}

/** Proprietes propres au composant. */
export interface CurrentsOwnProps {
  /** Vitesse d'advection. @defaultValue 0.2 */
  speed?: number
  /** Echelle du bruit. Plus haut, plus fin. @defaultValue 3 */
  scale?: number
  /** Anisotropie. Plus haut, filaments plus longs. @defaultValue 6 */
  stretch?: number
  /** Tokens dont les couleurs sont lues. */
  colors?: readonly string[]
  /** Classes du repli. */
  fallback?: string
  /** Echappatoire. */
  onReady?: ReadyCallback<CurrentsControls>
}

/** Toutes les proprietes. */
export type CurrentsProps = Customisable<CurrentsOwnProps>

/** Tokens employes par defaut : l'eau profonde, les courants, les filaments. */
const DEFAULT_TOKENS = [
  '--o-theme-bg',
  '--o-palette-teal-400',
  '--o-palette-cyan-200',
] as const

/** Repli par defaut : un degrade fige, dans les memes tons. */
const DEFAULT_FALLBACK = 'o-bg-gradient-to-b o-from-zinc-50 dark:o-from-blue-950 o-to-teal-950'

/**
 * Courants.
 *
 * @example
 * <div className="o-relative o-min-h-screen">
 *   <Currents className="o-absolute o-inset-0" />
 *   <main className="o-relative">…</main>
 * </div>
 */
export function Currents({
  speed = 0.2,
  scale = 3,
  stretch = 6,
  colors = DEFAULT_TOKENS,
  fallback = DEFAULT_FALLBACK,
  onReady,
  ...rest
}: CurrentsProps): ReactElement {
  const { ref, setHost, ready, refused, colours } = useTokenShader<HTMLDivElement>({
    fragment: CURRENTS_FRAGMENT,
    colors,
    uniforms: { uSpeed: speed, uScale: scale, uStretch: stretch, uDetail: 4 },
    name: 'currents',
    // Le champ d'ecoulement garde ses trois octaves — sans lui, plus de
    // courant du tout. Ce sont les octaves du bruit fin qui pesent, donc
    // c'est elles qui sont bornees.
    degrade: (quality) => ({
      uDetail: quality === 'low' ? 2 : 4,
    }),
  })

  useOnReady(onReady, ready ? { colours, refused } : null, ref.current)

  const { className, style } = mergePresentation(
    { className: 'o-relative o-overflow-hidden' },
    rest,
  )

  return (
    <div
      {...rest}
      ref={(element) => {
        setHost(element)
        ref.current = element
      }}
      className={className}
      style={style}
      aria-hidden
    >
      {ready && refused === undefined ? null : (
        <div className={`o-absolute o-inset-0 ${fallback}`} />
      )}
    </div>
  )
}
